func (r *AppStoreAppDataSourceModel) ToOperationsGetAppStoreAppRequest(ctx context.Context) (*operations.GetAppStoreAppRequest, diag.Diagnostics) {
	var diags diag.Diagnostics

	var appID string
	appID = r.AppID.ValueString()

	var expand []string
	if r.Expand != nil {
		expand = make([]string, 0, len(r.Expand))
		for expandIndex := range r.Expand {
			expand = append(expand, r.Expand[expandIndex].ValueString())
		}
	}
	out := operations.GetAppStoreAppRequest{
		AppID:  appID,
		Expand: expand,
	}

	return &out, diags
}

